package com.onlinelibrary.controller;
import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/member/borrow") public class BorrowBookServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{long id=Long.parseLong(r.getParameter("bookId"));long member=WebSupport.uid(r);long tx=WebSupport.SERVICE.borrow(member,id);var prefs=WebSupport.SERVICE.preferences().find(member);if(Boolean.TRUE.equals(prefs.get("dueDate")))new com.onlinelibrary.dao.impl.NotificationDAOImpl().create(member,"Book borrowed","Your book is due in "+com.onlinelibrary.util.DBConnection.loanDays()+" days.","DUE_DATE");s.sendRedirect(r.getContextPath()+"/member/history?message=Borrowing+created+%23"+tx);}catch(Exception e){WebSupport.fail(r,s,e);}}}
